/** Group flowers by family, preserving first-seen family order. */
export function flowersByFamily(list: Flower[] = FLOWERS): Array<{
  family: string;
  handle: string;
  flowers: Flower[];
}> {
  const order: string[] = [];
  const map = new Map<string, Flower[]>();
  for (const f of list) {
    if (!map.has(f.family)) {
      map.set(f.family, []);
      order.push(f.family);
    }
    map.get(f.family)!.push(f);
  }
  return order.map((fam) => ({
    family: fam,
    handle: familyHandle(fam),
    flowers: map.get(fam)!,
  }));
}
